    DEFAULT_DATA_BRANCH: DEFAULT_DATA_BRANCH,
    DEFAULT_DATA_PATH: DEFAULT_DATA_PATH,
    DEFAULT_ATTEMPTS: DEFAULT_ATTEMPTS
};

