function toWindowStart(value) {
    var text = String(value || todayIsoDay());
    return text.length === 10 ? text + 'T00:00:00Z' : text;
}

function toWindowEnd(value) {
    var text = String(value || todayIsoDay());
    return text.length === 10 ? text + 'T23:59:59Z' : text;
}

