        (res.path ? ' → ' + res.path : '') +
        (res.reason ? ' (' + res.reason + ')' : '') +
        ' [' + res.rowCount + ' rows / ' + res.keyCount + ' keys]' +
        (res.attempts ? ' after ' + res.attempts + ' attempt(s)' : '');
