        'readTokens', 'writeTokens', 'cachedTokens', 'reasoningTokens',
        'samples', 'resumeDetected', 'resumeStages',
        'feedbackLoopCount', 'rateLimitRetryCount', 'rateLimitDetected', 'timeoutCount',
        'source', 'url'
    ];
    var out = [headers.join(',')];
    rows.forEach(function(row) {
