function normalizeLogPayload(raw) {
    if (raw == null) return '';
    if (typeof raw !== 'string') {
        if (raw.result) return normalizeLogPayload(raw.result);
        if (raw.logs) return normalizeLogPayload(raw.logs);
        return JSON.stringify(raw);
